import { memoryTokenStore } from "../token-store/memory.js";
import { isExplicitLocalOAuthEnvironment } from "../url-utils.js";
/** Resolve the handler store without silently using process-local state in deployments. */
export function resolveOAuthHandlerTokenStore(tokenStore, env) {
    if (tokenStore)
        return tokenStore;
    if (isExplicitLocalOAuthEnvironment(env))
        return memoryTokenStore;
    throw new Error("OAuth handlers require an explicit shared TokenStore outside development/test");
}
